export const listOwnRoles = <ThrowOnError extends boolean = false>(options?: Options<ListOwnRolesData, ThrowOnError>): RequestResult<ListOwnRolesResponses, ListOwnRolesErrors, ThrowOnError> => (options?.client ?? client).get<ListOwnRolesResponses, ListOwnRolesErrors, ThrowOnError>({
    responseType: 'json',
    url: '/roles/me',
    ...options
});

/**
 * List the avatars an account may choose
 *
 * Public. Returns the preset ids and their URLs, so a picker can be rendered from any site without bundling the artwork per app.
 */
export const listAvatarPresets = <ThrowOnError extends boolean = false>(options?: Options<ListAvatarPresetsData, ThrowOnError>): RequestResult<ListAvatarPresetsResponses, ListAvatarPresetsErrors, ThrowOnError> => (options?.client ?? client).get<ListAvatarPresetsResponses, ListAvatarPresetsErrors, ThrowOnError>({
    responseType: 'json',
    url: '/users/avatar-presets',
    ...options
});

/**
 * Claim the first administrator slot
 *
 * Promotes the signed-in account, but only while no administrator exists. It is the bootstrap for a fresh deployment and fails once anyone holds the role.
 */
export const becomeSuperuser = <ThrowOnError extends boolean = false>(options?: Options<BecomeSuperuserData, ThrowOnError>): RequestResult<BecomeSuperuserResponses, BecomeSuperuserErrors, ThrowOnError> => (options?.client ?? client).post<BecomeSuperuserResponses, BecomeSuperuserErrors, ThrowOnError>({
    responseType: 'json',
    url: '/users/become-superuser',
    ...options
});

/**
 * Get the signed-in account
 */
